main :: IO ()
main = do
  let
    cashDebits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "Cash" && side p == Debit) journal)))) :: Int
    cashCredits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "Cash" && side p == Credit) journal)))) :: Int
    cashBalance = cashDebits - cashCredits
    taxCredits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "ConsumptionTaxReceived" && side p == Credit) journal)))) :: Int
    taxDebits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "ConsumptionTaxReceived" && side p == Debit) journal)))) :: Int
    taxBalance = taxCredits - taxDebits
    salesCredits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "Sales" && side p == Credit) journal)))) :: Int
    salesDebits = fromInteger (round (sum (map (\p -> amount p) (filter (\p -> account p == account "Sales" && side p == Debit) journal)))) :: Int
    salesBalance = salesCredits - salesDebits
    totalAssets = cashBalance
    totalLiabilities = taxBalance
    totalEquity = salesBalance
    totalRevenue = salesCredits
    totalExpenses = 0
    netIncome = totalRevenue - totalExpenses
    balanceCheck = totalAssets - (totalLiabilities + totalEquity)
  emitObject
    [ ("journal", JournalComp journal)
    , ("derived", RawComp (jFlatNum
        [ ("ledger.Cash.debits", cashDebits)
        , ("ledger.Cash.credits", cashCredits)
        , ("ledger.Cash.balance", cashBalance)
        , ("trial_balance.Cash", cashBalance)
        , ("ledger.ConsumptionTaxReceived.debits", taxDebits)
        , ("ledger.ConsumptionTaxReceived.credits", taxCredits)
        , ("ledger.ConsumptionTaxReceived.balance", taxBalance)
        , ("trial_balance.ConsumptionTaxReceived", taxBalance)
        , ("ledger.Sales.debits", salesDebits)
        , ("ledger.Sales.credits", salesCredits)
        , ("ledger.Sales.balance", salesBalance)
        , ("trial_balance.Sales", salesBalance)
        , ("financial_statements.total_assets", totalAssets)
        , ("financial_statements.total_liabilities", totalLiabilities)
        , ("financial_statements.opening_equity", 0)
        , ("financial_statements.total_equity", totalEquity)
        , ("financial_statements.total_revenue", totalRevenue)
        , ("financial_statements.total_expenses", totalExpenses)
        , ("financial_statements.net_income", netIncome)
        , ("financial_statements.balance_check", balanceCheck)
        ]))
    ]
